def transform(grid):
    # Temporary generic selection by largest compact solid-color component; refine from demos.
    from collections import deque
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        color=grid[r][c]
        if color in (0,7,9) or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); pts=[]
        while q:
          y,x=q.pop(); pts.append((y,x))
          for dy,dx in ((0,1),(0,-1),(1,0),(-1,0)):
            p=(y+dy,x+dx)
            if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
              seen.add(p);q.append(p)
        comps.append((color,pts))
    color,pts=max(comps,key=lambda x:len(x[1]))
    return [[color]]
